define(["jquery"],function(e){"use strict";return{init:function(t,n,r){const i=e("[data-region='qrcodecheck-project']");if(!i.length)return;const c=i.find("[data-region='qrcode-image']"),o=i.find("[data-region='qrcode-countdown']");let a=Math.floor(Date.now()/1e3/r);const d=function(){const e=Math.floor(Date.now()/1e3),t=Math.floor(e/r);let n=r-e%r;n<=0&&(n=r),o.text(n),t!==a&&(a=t,(()=>{const e=-1===c.attr("src").indexOf("?")?"?":"&",t=c.attr("src").replace(/([?&])v=\d+/,"$1").replace(/[?&]$/,"");c.attr("src",t+e+"v="+Date.now())})())};d(),window.setInterval(d,250)}}});
